"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["49827"],{32425(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.motivo_de_decisao.avaliacao_iniciada","status":422,"titulo":"A avalia\xe7\xe3o nesta fase ou etapa j\xe1 come\xe7ou"},"descricao":{"codigo":"uniplus.selecao.motivo_de_decisao.avaliacao_iniciada","requisitos":["UNI-REQ-0124","UNI-REQ-0285"],"oQueAconteceu":["Depois da publica\xe7\xe3o, o motivo novo s\xf3 entra antes do in\xedcio da avalia\xe7\xe3o daquela decis\xe3o (UNI-REQ-0124 e UNI-REQ-0285). A avalia\xe7\xe3o come\xe7a no que vier primeiro: o in\xedcio do per\xedodo da fase em que a decis\xe3o \xe9 avaliada, ou de uma etapa dela, no cronograma, ou o primeiro registro de decis\xe3o daquele tipo. \xc9 a mesma regra de fase iniciada do UNI-REQ-0333. O pedido de `PUT /api/selecao/processos-seletivos/{id}/motivos-de-decisao/{motivoId}` chegou depois desse instante, que conta como j\xe1 come\xe7ado. A recusa sai com **422**, e o `detail` diz o tipo da decis\xe3o."],"comoResolver":["A avalia\xe7\xe3o j\xe1 em curso usa s\xf3 os motivos publicados. Se falta motivo para um caso, a decis\xe3o usa o motivo mais pr\xf3ximo da lista, com a justificativa explicando o caso (UNI-REQ-0286)."],"ondeAparece":["Inclus\xe3o de motivo no processo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Motivo de decisao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);